Object.assign(ITEMS, Object.fromEntries([
  wearBody('fxtutudress', '紫黑蓬蓬纱裙', 'Purple & black tutu dress', 240, { a: '#b48cf0', b: '#2a2532', c: '#e9dcff', w: '#ffffff' },
    (x, y, p) => (y <= 0 ? p.c : y <= 4 ? (Math.abs(x) >= 5 ? p.c : p.a) : y === 5 ? p.c
      : (Math.floor((y - 6) / 2) % 2 ? p.b : ((x + y) % 4 === 0 ? p.w : p.a))), DRESS),
  wearBody('fxbutterflydress', '紫色蝴蝶纱裙', 'Lilac butterfly tulle dress', 220, { a: '#c9a6ff', b: '#9b6bd6', c: '#efe4ff', p: '#ff8fb3', y: '#ffd23f', s: '#7fd0ff', w: '#ffffff' },
    (x, y, p) => (y <= 4 ? (Math.abs(x) >= 5 && y <= 2 ? p.c : p.a) : y === 5 ? (Math.abs(x) >= 1 && Math.abs(x) <= 3 ? p.b : x === 0 ? p.c : p.a)
      : ((x * 7 + y * 3) % 9 === 0 ? [p.p, p.y, p.s][(y + 9) % 3] : (x + 2 * y) % 6 === 0 ? p.w : p.a)), DRESS),
]));
['fxpinkfurbag', 'fxlilactote', 'fxlilacbackpack', 'fxblackcatbag', 'fxtutudress', 'fxbutterflydress', 'fxbrowntote', 'fxcrescentbag', 'fxbarrelbag', 'fxquiltblack', 'fxquiltpink']
  .forEach((id) => { ITEMS[id].special = true; ITEMS[id].mallOnly = true; if (!FASHION_EXCLUSIVE.includes(id)) FASHION_EXCLUSIVE.push(id); });
// the older wearable handbags were too big on the kitten: draw them 30% smaller
const shrinkArt = (art, f) => { const h = Math.round(art.length * f), w = Math.round(art[0].length * f);
  return Array.from({ length: h }, (_, y) => Array.from({ length: w }, (_, x) => art[Math.min(art.length - 1, Math.floor(y / f))][Math.min(art[0].length - 1, Math.floor(x / f))]).join('')); };
['luxetotewear', 'luxeflapwear', 'luxebucketwear', 'luxesaddlewear', 'luxeclutchwear'].forEach((id) => {
  const it = ITEMS[id]; if (!it) return;
  const art = shrinkArt(it.art, 0.7), w = art[0].length, h = art.length;
  ITEMS[id] = { ...it, art, wear: { x: 16 + Math.floor((13 - w) / 2), y: 37 - h } };
});

// v189: 👜 handbags have their own spot (so she can wear a bag AND a scarf / bow tie)
['fxpinkfurbag', 'fxlilactote', 'fxblackcatbag', 'fxbrowntote', 'fxcrescentbag', 'fxbarrelbag', 'fxquiltblack', 'fxquiltpink',
  'luxetotewear', 'luxeflapwear', 'luxebucketwear', 'luxesaddlewear', 'luxeclutchwear'].forEach((id) => { if (ITEMS[id]) ITEMS[id].slot = 'bag'; });

